import json
from glob import glob
import os
def task_func(directory, string):
    json_files = glob(os.path.join(directory, '**', '*.json'), recursive=True)
    result = []
    for file_path in json_files:
        with open(file_path, 'r') as f:
            try:
                data = json.load(f)
                if any(string in str(value) for value in _flatten_dict(data)):
                    result.append(file_path)
            except json.JSONDecodeError:
                continue
    return result
def _flatten_dict(d):
    if isinstance(d, dict):
        for value in d.values():
            yield from _flatten_dict(value)
    elif isinstance(d, list):
        for item in d:
            yield from _flatten_dict(item)
    else:
        yield d

